.darma-loader-tw-pill-loader { position: relative; overflow: hidden; width: var(--loader-size, 150px); height: calc(var(--loader-size, 150px) * .28); border-radius: 9999px; border: calc(var(--loader-size, 150px) * .025) solid var(--loader-color, #ec4899); box-sizing: border-box; }
.darma-loader-tw-pill-loader .darma-loader-tw-pill-loader__fill { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; background: var(--loader-color, #ec4899); animation: darma-loader-tw-pill-loader-twGrow calc(var(--loader-speed, 1s) * 1.8) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes darma-loader-tw-pill-loader-twGrow { 0% { transform: scaleX(0); transform-origin: left center; } 45% { transform: scaleX(1); transform-origin: left center; } 55% { transform: scaleX(1); transform-origin: right center; } 100% { transform: scaleX(0); transform-origin: right center; } }

